    // Prover-commitment transport class (witness only). Owns its own storage.
    template <typename DataType_> class WitnessEntities {
      public:
        using DataType = DataType_;
        std::array<DataType, NUM_WITNESS_ENTITIES> data{};

        bool operator==(const WitnessEntities&) const = default;

        std::span<DataType, NUM_WITNESS_ENTITIES> get_all() { return data; }
        std::span<const DataType, NUM_WITNESS_ENTITIES> get_all() const { return data; }

        static constexpr size_t size() { return NUM_WITNESS_ENTITIES; }

        // Named accessor methods — index into local `data` (NOT the AllEntities layout).
        DataType& w_l() { return data[0]; }
        const DataType& w_l() const { return data[0]; }
        DataType& w_r() { return data[1]; }
        const DataType& w_r() const { return data[1]; }
        DataType& w_o() { return data[2]; }
        const DataType& w_o() const { return data[2]; }
        DataType& w_4() { return data[3]; }
        const DataType& w_4() const { return data[3]; }
        DataType& z_perm() { return data[4]; }
        const DataType& z_perm() const { return data[4]; }
        DataType& lookup_inverses() { return data[5]; }
        const DataType& lookup_inverses() const { return data[5]; }
        DataType& lookup_read_counts() { return data[6]; }
        const DataType& lookup_read_counts() const { return data[6]; }
        DataType& lookup_read_tags() { return data[7]; }
        const DataType& lookup_read_tags() const { return data[7]; }

        // Subset views.
        RefArray<DataType, 4> get_wires() { return { this->w_l(), this->w_r(), this->w_o(), this->w_4() }; }
        RefArray<const DataType, 4> get_wires() const { return { this->w_l(), this->w_r(), this->w_o(), this->w_4() }; }

        RefArray<DataType, 5> get_to_be_shifted()
        {
            return { this->w_l(), this->w_r(), this->w_o(), this->w_4(), this->z_perm() };
        }
        RefArray<const DataType, 5> get_to_be_shifted() const
        {
            return { this->w_l(), this->w_r(), this->w_o(), this->w_4(), this->z_perm() };
        }

        static const std::vector<std::string>& get_labels()
        {
            static const std::vector<std::string> labels = {
                "W_L", "W_R", "W_O", "W_4", "Z_PERM", "LOOKUP_INVERSES", "LOOKUP_READ_COUNTS", "LOOKUP_READ_TAGS",
            };
            return labels;
        }
    };
